#!/usr/bin/env python3
"""Deterministic generator for the 24 November 2026 news-image entry.

The front page (1024x1024 JPEG) is embedded below as base64. Running
this program writes the exact same bytes to /output/entry.png every
time: no network, no randomness, no timestamps, stdlib only.
Re-running is safe: it overwrites the output file with identical bytes.
Verified locally on 24 November 2026: two runs write byte-identical
output (SHA-256 checked), and the image is 1024x1024, 301,096 bytes,
inside the 1 MiB limit.

Layout: a newspaper front page ("THE WORLD IN ONE IMAGE") built from
four photo panels -- Nvidia's Jensen Huang reinstated as CEO and the
market surge, Russian warplanes in South Korea's air defence zone,
the Indonesian factory fire, and the Gulf tanker standoff -- with a
footer of briefs. All facts were verified against Reuters, CNN, AP,
The Wall Street Journal, BBC, ATP and the Times of India on
24 November 2026.
"""

import base64
import hashlib
import os
import sys

# Base64 of the 1024x1024 front-page JPEG (301,096 bytes).

IMAGE_B64 = ""

EXPECTED_SHA256 = "8481efff5d5fb85eb52a484c2ae48c16d832707a6ebe2067b0e47acb2f4de75a"
EXPECTED_SIZE = 301096


def main():
    data = base64.b64decode(IMAGE_B64)
    if len(data) != EXPECTED_SIZE:
        sys.exit(f"embedded image size mismatch: {len(data)} bytes")
    if hashlib.sha256(data).hexdigest() != EXPECTED_SHA256:
        sys.exit("embedded image failed SHA-256 integrity check")
    out = os.environ.get("OUTPUT", "/output/entry.png")
    parent = os.path.dirname(out)
    if parent:
        os.makedirs(parent, exist_ok=True)
    with open(out, "wb") as fh:
        fh.write(data)
    print(f"wrote {out} ({len(data)} bytes, sha256 {EXPECTED_SHA256[:16]}...)")


if __name__ == "__main__":
    main()
